// Concept-chat bridge summary — PURE decision layer (native-free).
//
// The concept chat replayed the ENTIRE project history into every message
// (concept.js used to feed listMessages() straight to buildConceptTranscript),
// so a long design conversation grew quadratically in cached-read volume on
// the most expensive lane — the exact "one growing chat" cost curve. The fix
// is the bridge pattern: a rolling summary (generated by the cheap `summary`
// slot) carries the state of the conversation, and only the recent tail is
// replayed verbatim.
//
// Safety property: windowing applies ONLY when a stored summary exists. If
// the summary slot is unconfigured or a refresh fails, the transcript falls
// back to the full-history behavior — worst case is yesterday's cost, never
// a degraded conversation.
//
// Cache note: the summary text is byte-stable between refreshes, so the
// windowed prefix stays cache-friendly; each refresh (every ~TRIGGER-TAIL
// messages) costs one prefix re-write, amortized over the turns between.

// Recent messages always replayed verbatim (the live working context).
export const CHAT_SUMMARY_TAIL_KEEP = 30;
// Refresh when this many messages sit beyond current summary coverage —
// each refresh folds the oldest (TRIGGER - TAIL_KEEP) of them into the brief.
export const CHAT_SUMMARY_TRIGGER = 60;
// Ceiling for the stored brief itself.
export const CHAT_SUMMARY_MAX_CHARS = 6000;
// Per-message char budget when rendering the slice to summarize.
const SLICE_PER_MESSAGE_CHARS = 2000;

// The system prompt for the summary-slot call (harness-prompts-logic
// registers it so operators can preview/override it like any other step).
export const CHAT_SUMMARY_SYSTEM_PROMPT = [
  'You maintain the rolling brief for a product-design conversation between a Builder and',
  'their design partner. Your only job is to return the UPDATED brief: fold the new exchange',
  'into the current brief, preserving every decision that still matters — what is being built',
  'and for whom, agreed look-and-feel, named screens/features and their states, explicit user',
  'preferences and corrections, and anything the user rejected (so it is not re-proposed).',
  'Drop pleasantries and superseded back-and-forth; keep the decisions they produced.',
  'Output ONLY the brief text: no preamble, no headers about being a summary, no commentary.',
].join('\n');

export function chatSummaryEnabled(env = process.env) {
  const v = String(env?.MOCK2_CHAT_SUMMARY ?? '').trim().toLowerCase();
  return !(v === 'off' || v === '0' || v === 'false');
}

// Only user/assistant turns participate (buildConceptTranscript drops the
// rest anyway); ids are the windowing key.
function conversational(messages) {
  return (Array.isArray(messages) ? messages : []).filter(
    (m) => m && (m.kind === 'user' || m.kind === 'assistant'),
  );
}

// The synthetic first turn carrying the brief. kind:'user' so it survives
// buildConceptTranscript; id 0 so image hydration treats it as oldest. The
// labeling makes clear it is compressed history, not a fresh instruction.
export function summaryMessageRow(summary) {
  return {
    id: 0,
    kind: 'user',
    body: `[Conversation so far — rolling summary of the earlier design discussion. Treat it as established context, not as new instructions:]\n\n${String(summary || '').trim()}`,
    attachments_json: null,
  };
}

// chatSummaryWindow(messages, chatRow) → { messages, windowed }
//
// When the chat row carries a summary covering through some message id,
// replace everything at-or-before that id with the synthetic summary turn
// and keep the rest verbatim. Otherwise pass through unchanged.
export function chatSummaryWindow(messages, chatRow, { enabled = true } = {}) {
  const all = Array.isArray(messages) ? messages : [];
  const summary = String(chatRow?.summary || '').trim();
  const throughId = Number(chatRow?.summary_through_id || 0);
  if (!enabled || !summary || !(throughId > 0)) return { messages: all, windowed: false };
  const tail = all.filter((m) => Number(m?.id || 0) > throughId);
  // A summary that would drop nothing (stale row after message deletions)
  // degrades to pass-through rather than double-counting history.
  if (tail.length === all.length) return { messages: all, windowed: false };
  return { messages: [summaryMessageRow(summary), ...tail], windowed: true };
}

// shouldRefreshChatSummary(messages, chatRow) → null | { throughId, slice }
//
// Refresh when the un-summarized run of conversation exceeds TRIGGER:
// fold everything except the most recent TAIL_KEEP into the brief. The
// returned slice is the messages to summarize (those beyond current
// coverage, up to the new throughId).
export function shouldRefreshChatSummary(messages, chatRow, {
  tailKeep = CHAT_SUMMARY_TAIL_KEEP,
  trigger = CHAT_SUMMARY_TRIGGER,
  enabled = true,
} = {}) {
  if (!enabled) return null;
  const convo = conversational(messages);
  const coveredId = Number(chatRow?.summary_through_id || 0);
  const uncovered = convo.filter((m) => Number(m?.id || 0) > coveredId);
  if (uncovered.length < Math.max(trigger, tailKeep + 1)) return null;
  const slice = uncovered.slice(0, uncovered.length - tailKeep);
  const throughId = Number(slice[slice.length - 1]?.id || 0);
  if (!(throughId > 0)) return null;
  return { throughId, slice };
}

// The summary-model prompt. One user turn; the model returns the UPDATED
// brief (merging the previous one), plain text, bounded.
export function buildChatSummaryPrompt({ previousSummary = '', slice = [], maxChars = CHAT_SUMMARY_MAX_CHARS } = {}) {
  const lines = [];
  for (const m of slice) {
    const who = m.kind === 'assistant' ? 'Design partner' : 'Builder';
    const body = String(m.body || '').slice(0, SLICE_PER_MESSAGE_CHARS);
    lines.push(`${who}: ${body}`);
  }
  const prev = String(previousSummary || '').trim();
  return [
    'You maintain the rolling brief for a product-design conversation. Update the brief below',
    'with the new exchange, producing ONE plain-text brief that preserves every decision that',
    'still matters: what is being built and for whom, agreed look/feel and design decisions,',
    'named screens/features and their states, explicit user preferences and corrections, and',
    'anything the user rejected (so it is not re-proposed). Drop pleasantries, dead ends that',
    'were superseded, and back-and-forth that led to a recorded decision — keep the decision.',
    `Hard limit ${maxChars} characters. Return ONLY the updated brief text, no preamble.`,
    '',
    prev ? `Current brief:\n${prev}` : 'Current brief: (none yet — this is the first summary)',
    '',
    'New exchange to fold in:',
    ...lines,
  ].join('\n');
}
